from __future__ import annotations


class Group:
    def __init__(self, members: list[str]) -> None:
        self._members: list[str] = list(members)
        self._member_set = set(self._members)
        # balance in cents; positive = owed, negative = owes
        self._balance_cents: dict[str, int] = {m: 0 for m in self._members}

    def add_expense(self, payer: str, amount: float,
                    participants: list[str] | None = None) -> None:
        if payer not in self._member_set:
            raise ValueError(f"Unknown payer: {payer!r}")
        if amount <= 0:
            raise ValueError("Amount must be positive")

        if participants is None:
            participants = self._members
        else:
            participants = list(participants)
            if not participants:
                raise ValueError("Participants list cannot be empty")
            for p in participants:
                if p not in self._member_set:
                    raise ValueError(f"Unknown participant: {p!r}")

        total_cents = round(amount * 100)
        if total_cents <= 0:
            raise ValueError("Amount must be positive")

        n = len(participants)
        # equal split; leftover cents borne by payer
        share, remainder = divmod(total_cents, n)
        # If payer is among participants, payer's true share is share + remainder
        # (rounded down for everyone else; payer absorbs the remainder).
        # If payer is not a participant, distribute remainder to payer too:
        # everyone else pays floor, payer pays the rest of the cost anyway.

        if payer in participants:
            others = [p for p in participants if p != payer]
        else:
            others = participants

        # each "other" owes floor share
        others_owed = share  # rounded down (share is already floor)
        for p in others:
            self._balance_cents[p] -= others_owed
            self._balance_cents[payer] += others_owed

        if payer in participants:
            # payer's own share is total - others_owed * len(others)
            payer_share = total_cents - others_owed * len(others)
            self._balance_cents[payer] -= payer_share
            self._balance_cents[payer] += payer_share  # net zero for own share
        # If payer not in participants, they paid for all others:
        # already accounted: each other paid others_owed to payer.

    def balances(self) -> dict[str, float]:
        return {m: self._balance_cents[m] / 100.0 for m in self._members}

    def settle_up(self) -> list[tuple[str, str, float]]:
        # Only consider debts >= 1.00 (100 cents); smaller ones written off
        debtors: list[list] = []   # [member, amount_cents]
        creditors: list[list] = []
        for m in self._members:
            b = self._balance_cents[m]
            if b <= -100:
                debtors.append([m, -b])
            elif b >= 100:
                creditors.append([m, b])

        # Sort for deterministic output: largest first
        debtors.sort(key=lambda x: (-x[1], x[0]))
        creditors.sort(key=lambda x: (-x[1], x[0]))

        payments: list[tuple[str, str, float]] = []
        di = 0
        ci = 0
        while di < len(debtors) and ci < len(creditors):
            d_member, d_amt = debtors[di]
            c_member, c_amt = creditors[ci]
            pay = min(d_amt, c_amt)
            if pay >= 100:
                payments.append((d_member, c_member, pay / 100.0))
            d_amt -= pay
            c_amt -= pay
            debtors[di][1] = d_amt
            creditors[ci][1] = c_amt
            if d_amt < 100:
                di += 1
            if c_amt < 100:
                ci += 1

        return payments
